import {LOCAL_PROCEDURES,LOCAL_TOOLS,localTitle} from './local-or.js';
import {EAR_POINTS,ORAL_POINTS,localTool,localVisual} from './local-or-art.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const actionButton=(text,action,value='',extra='')=>`<button class="secondary-button" data-local-action="${action}" data-local-value="${value}" ${extra}>${text}</button>`;
const tools=(ids,action)=>`<div class="npx-tools">${ids.map(id=>`<button data-local-action="${action}" data-local-value="${id}" aria-label="${action==='instrument'?'請刷手遞':''}${LOCAL_TOOLS.find(t=>t.id===id).name}">${localTool(id)}<b>${action==='instrument'?'請刷手遞':''}${LOCAL_TOOLS.find(t=>t.id===id).name}</b></button>`).join('')}</div>`;
export function localHTML(t,{near=false}={}){
  const c=LOCAL_PROCEDURES[t.kind],stage=t.stage,team=stage==='handoff'?'流動':null,step=c.stages.indexOf(stage)+1;
  let body='',hits='';
  if(!near)body=`<p>這一步要到${team||'手術台'}旁。已完成的部分都還在。</p><button id="localWalk" class="primary-button">走近${team||'手術台'} →</button>`;
  else if(stage==='verify')body=`<div class="npx-paper"><small>流動交來的本台資料</small><strong>${esc(t.patient.name)}</strong><span>${esc(c.name)} · ${esc(t.attending)}${t.kind==='ear'?'<br>本台：右耳':''}</span></div><p>和刀單核對，這位病人是誰？</p><div class="npx-names">${[{id:'E13-01',name:'王以辰'},{id:'O13-01',name:'張宜庭'},{id:'P13-01',name:'林予安'}].map(p=>actionButton(p.name,'verify',p.id)).join('')}</div>`;
  else if(stage==='headlamp')body=`<p>先戴好頭燈，準備看清口腔病灶。</p><button class="local-large-tool" data-local-action="headlamp">${localTool('headlamp')}<b>戴好頭燈 →</b></button>`;
  else if(stage==='drape'){body='<p>點選三處待鋪位置，完成這一台的簡單鋪單。</p>';hits=[{x:31,y:36},{x:69,y:36},{x:50,y:76}].map((p,i)=>t.drapes.includes(i)?'':`<button class="npx-hit drape-hit" style="left:${p.x}%;top:${p.y}%" data-local-action="drape" data-local-value="${i}" aria-label="鋪好第${i+1}處">＋ 鋪單</button>`).join('');}
  else if(stage==='local')body=`<p>${t.kind==='ear'?'依這台安排先噴 local，接著簡單鋪單。':'頭燈與病灶都確認了，選本台局部麻醉用品。'}</p>${tools(['spray','syringe','swab'],'local')}`;
  else if(stage==='scope'){body='<p>依畫面標示，確認鼓膜前下方。</p><div class="npx-assist-note">上、下、前、後都在視野旁，先看方向再選。</div>';hits=EAR_POINTS.map(p=>`<button class="npx-hit local-hit" style="left:${p.x}%;top:${p.y}%" data-local-action="inspect" data-local-value="${p.id}" aria-label="確認${p.label}">${p.label}</button>`).join('');}
  else if(stage==='inspect'){body='<p>頭燈亮了，找出不規則的口腔病灶。</p>';hits=ORAL_POINTS.map((p,i)=>`<button class="npx-hit scope-hit" style="left:${p.x}%;top:${p.y}%" data-local-action="inspect" data-local-value="${i}" aria-label="觀察口腔${p.label}">觀察</button>`).join('');}
  else if(stage==='instrument')body=`<p>刷手就在手術台旁：「需要哪一樣？我遞給你。」</p>${tools(['injection','biopsy','swab'],'instrument')}`;
  else if(stage==='inject'){body='<p>刷手把注射器遞到你手上。對準剛才確認的前下方。</p><div class="npx-held-tool">'+localTool('injection')+'<span>耳內注射用注射器</span></div>';hits='<button class="npx-hit hold-hit" style="left:38%;top:65%" data-local-hold="inject" data-local-value="anterior-inferior">按住完成注射</button>';}
  else if(stage==='rest')body=`<div class="local-rest"><b>讓病人躺著休息10分鐘</b><p>依這台交代，先不要說話或吞口水。</p><button class="secondary-button" data-local-action="explain-rest" ${t.restExplained?'disabled':''}>${t.restExplained?'✓ 已向病人交代':'向病人交代休息注意事項'}</button>${!t.restStarted?'<button class="primary-button" data-local-action="start-rest">開始休息計時 →</button>':''}<div class="local-rest-track" role="progressbar" aria-label="休息分鐘" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${Math.floor(t.restElapsed)}">${Array.from({length:10},(_,i)=>`<i class="${t.restElapsed>=i+1?'filled':''}"></i>`).join('')}</div><strong id="localRestTime">${Math.floor(t.restElapsed)} / 10 分鐘</strong><small>每格代表遊戲內1分鐘。先回房內也會保留計時。</small><button id="localRestFinish" class="primary-button" data-local-action="finish-rest" ${t.restElapsed<10?'disabled':''}>休息完成，再確認病人狀況 →</button></div>`;
  else if(stage==='check')body=`<p>休息結束，先問狀況，再交代後續。</p>${actionButton(t.checked.includes('feeling')?'✓ 病人目前沒有新的不適':'詢問休息後有沒有不舒服','check','feeling',t.checked.includes('feeling')?'disabled':'')}${actionButton(t.checked.includes('instructions')?'✓ 已確認後續回診安排':'交代後續回診安排','check','instructions',t.checked.includes('instructions')?'disabled':'')}<button class="primary-button" data-local-action="finish" ${t.checked.length<2?'disabled':''}>完成這台耳內注射 ✓</button>`;
  else if(stage==='sample'){const p=ORAL_POINTS[t.lesion];body='<p>刷手把切片器械遞到你手上。對準剛才看到的病灶取下檢體。</p>';hits=`<button class="npx-hit hold-hit" style="left:${p.x}%;top:${p.y}%" data-local-hold="sample" data-local-value="${t.lesion}">按住取檢體</button>`;}
  else if(stage==='cautery'){body='<p>檢體已取下，選電燒筆完成本台止血。</p>'+tools(['cautery','spray','swab'],'cautery');}
  else if(stage==='label')body=`<p>這一份來自 <b>${esc(t.patient.name)}</b>的<b>口腔</b>，選正確標示。</p><div class="npx-labels">${[{id:'patient',patient:'王以辰',site:'口腔'},{id:'correct',patient:t.patient.name,site:'口腔'},{id:'site',patient:t.patient.name,site:'鼻咽'}].map(l=>`<button data-local-action="label" data-local-value="${l.id}"><small>病理檢體</small><strong>${esc(l.patient)}</strong><span>部位：${l.site}</span></button>`).join('')}</div>`;
  else if(stage==='handoff')body=`<div class="npx-paper"><small>止血完成 · 檢體標示已核對</small><strong>${esc(t.patient.name)}</strong><span>口腔檢體 · ${esc(t.attending)}</span></div><button class="primary-button" data-local-action="handoff">核對標示，把檢體交給流動 ✓</button>`;
  const support=near&&(t.kind==='ear'?['scope','inject']:['inspect','sample','cautery']).includes(stage);
  return`<h2 id="modalTitle">${localTitle(t)}</h2><div class="npx-patient-line"><b>${esc(t.patient.name)}</b><span>${esc(c.name)} · ${esc(t.attending)}</span></div><div class="npx-tracker"><span>${String(step).padStart(2,'0')} / ${c.stages.length-1}</span><span>${t.kind==='ear'?'準備 → 注射 → 休息':'準備 → 切片 → 交接'}</span></div><div class="npx-layout"><div class="npx-visual">${localVisual(t)}${near?hits:''}<span class="npx-view-caption">13房 · 本台簡化視野</span></div><div class="npx-work">${body}${t.seniorJoined?'<div class="npx-assist-note">學長已一起回13房，需要時可以請他協助。</div>':''}<p id="localFeedback" class="npx-feedback" role="status">${esc(t.feedback)}</p>${support?`<button id="localSupport" class="text-button">${t.seniorJoined?'請學長協助這一步':'需要學長協助，去16房找他'} →</button>`:''}</div></div><div class="npx-bottom"><small>科內娛樂的簡化情境</small><button id="localLater" class="text-button">先回房內，進度保留 →</button>${t.practice?'<button id="localCases" class="text-button">選擇另一台手術 →</button>':''}</div>`;
}
export function bindLocalOR(t,{act,walk,later,choose,active}){
  const value=b=>['drape'].includes(b.dataset.localAction)||b.dataset.localAction==='inspect'&&t.kind==='oral'?Number(b.dataset.localValue):b.dataset.localValue;
  document.querySelectorAll('[data-local-action]').forEach(b=>b.onclick=()=>act(b.dataset.localAction,value(b)));
  document.querySelectorAll('[data-local-hold]').forEach(b=>{let timer;const stage=t.stage,clear=()=>{clearTimeout(timer);b.classList.remove('holding');};const commit=()=>{clear();if(b.isConnected&&active()&&t.stage===stage)act(b.dataset.localHold,t.kind==='ear'?b.dataset.localValue:Number(b.dataset.localValue));};b.onpointerdown=e=>{if(e.button!==0)return;b.setPointerCapture(e.pointerId);clear();b.classList.add('holding');timer=setTimeout(commit,700);};b.onpointerup=b.onpointercancel=b.onblur=clear;b.onclick=e=>{if(e.detail===0)commit();};});
  const byId=id=>document.getElementById(id);if(byId('localWalk'))byId('localWalk').onclick=walk;if(byId('localSupport'))byId('localSupport').onclick=()=>act('support');if(byId('localCases'))byId('localCases').onclick=choose;byId('localLater').onclick=later;
}
